INSERT INTO moadbook_games.question_bank
  (question_id,category_id,category,difficulty,prompt,options,correct_index,explanation,source_title,source_url,source_evidence,enabled)
SELECT q.id, q."categoryId", q.category, q.difficulty, q.prompt,
       ARRAY(SELECT jsonb_array_elements_text(q.options)), q."correctIndex", q.explanation,
       COALESCE(NULLIF(q."sourceTitle",''),'تحقق حسابي مباشر'), q."sourceUrl", COALESCE(NULLIF(q."sourceEvidence",''),q."verificationMethod",'مراجعة حسابية داخلية'), true
FROM jsonb_to_recordset($moadbook_questions$[
{"id":"tech-03","categoryId":"technology","category":"تقنية","difficulty":"easy","prompt":"ما النتيجة الأساسية لعملية التشفير؟","options":["تحويل البيانات إلى نص مشفّر يخفي معناها","ضغط البيانات لتقليل حجمها دائمًا","نسخ البيانات إلى جهاز آخر","حذف البيانات بعد قراءتها"],"correctIndex":0,"explanation":"يحوّل التشفير البيانات إلى نص مشفّر يحجب معناها؛ وتُسمى عملية إعادتها إلى حالتها الأصلية فك التشفير.","sourceTitle":"encryption - Glossary | CSRC","sourceUrl":"https://csrc.nist.gov/glossary/term/encryption","sourceEvidence":"يعرّف معجم NIST التشفير بأنه تحويل تشفيري للبيانات لإنتاج ciphertext، ويذكر أن التحويل العكسي يسمى decryption."},
{"id":"tech-04","categoryId":"technology","category":"تقنية","difficulty":"medium","prompt":"متى يمثّل عنصر HTML <a> رابطًا تشعبيًا؟","options":["عندما يحتوي على الخاصية href","عندما يحتوي على الخاصية title","عندما يكون داخل عنصر <p>","عندما يحتوي على نص طويل"],"correctIndex":0,"explanation":"بحسب معيار HTML، يمثل عنصر <a> رابطًا تشعبيًا عندما تتوفر له الخاصية href؛ ومن دونها يكون عنصرًا نائبًا لموضع قد يوضع فيه رابط.","sourceTitle":"HTML Standard: The a element","sourceUrl":"https://html.spec.whatwg.org/multipage/text-level-semantics.html#the-a-element","sourceEvidence":"ينص المعيار على أن عنصر a إذا احتوى على href فإنه يمثل رابطًا تشعبيًا، وإذا لم يحتوِ عليها فهو عنصر نائب."},
{"id":"cult-01","categoryId":"culture","category":"ثقافة وفنون","difficulty":"easy","prompt":"إلى أي سلسلة تنتمي مطبوعة «تحت الموجة قبالة كاناغاوا» لهوكوساي؟","options":["مناظر جبل فوجي الستة والثلاثون","مئة منظر لإيدو","مشاهد من طريق توكايدو","حكايات موجات البحر"],"correctIndex":0,"explanation":"تُدرج صفحة متحف المتروبوليتان العمل ضمن سلسلة «مناظر جبل فوجي الستة والثلاثون».","sourceTitle":"Under the Wave off Kanagawa (Kanagawa oki nami ura), also known as The Great Wave, from the series Thirty-six Views of Mount Fuji (Fugaku sanjūrokkei)","sourceUrl":"https://www.metmuseum.org/art/collection/search/45434","sourceEvidence":"يسجل المتحف أن العمل لهوكوساي ومن سلسلة Thirty-six Views of Mount Fuji، وأن وسيطه طباعة خشبية بالحبر والألوان على الورق."},
{"id":"cult-02","categoryId":"culture","category":"ثقافة وفنون","difficulty":"easy","prompt":"في أي عام نُشرت الطبعة الأولى المجمّعة لمسرحيات شكسبير المعروفة باسم «الفوليو الأول»؟","options":["1598","1603","1623","1660"],"correctIndex":2,"explanation":"تذكر مكتبة فولجر أن الفوليو الأول نُشر عام 1623، وجمع 36 مسرحية لشكسبير.","sourceTitle":"The Shakespeare First Folio","sourceUrl":"https://www.folger.edu/explore/shakespeare-in-print/first-folio/","sourceEvidence":"تقول صفحة فولجر إن First Folio published in 1623، وتذكر في الأسئلة الشائعة أنه تضمّن 36 مسرحية."},
{"id":"cult-03","categoryId":"culture","category":"ثقافة وفنون","difficulty":"medium","prompt":"ترتبط رقصة التانغو، كما أدرجتها اليونسكو ضمن التراث الثقافي غير المادي، بأي مدينتين؟","options":["بوينس آيرس ومونتفيديو","ليما وسانتياغو","هافانا وسانتو دومينغو","ريو دي جانيرو وساو باولو"],"correctIndex":0,"explanation":"توضح اليونسكو أن تقليد التانغو الأرجنتيني والأوروغواياني تطور في بوينس آيرس ومونتفيديو.","sourceTitle":"Tango","sourceUrl":"https://ich.unesco.org/en/RL/tango-00258","sourceEvidence":"تنص صفحة اليونسكو على أن التانغو تطور في بوينس آيرس ومونتفيديو، وأنه تراث مشترك للأرجنتين والأوروغواي."},
{"id":"cult-04","categoryId":"culture","category":"ثقافة وفنون","difficulty":"medium","prompt":"بأي مادة شُيّدت بيوت الأبراج التقليدية في مدينة شبام القديمة؟","options":["الطوب الطيني المجفف بالشمس","الحجر البركاني المصقول","الخشب المنحوت","الرخام الأبيض"],"correctIndex":0,"explanation":"تصف اليونسكو بيوت شبام البرجية بأنها مبنية من طوب طيني مجفف بالشمس.","sourceTitle":"Old Walled City of Shibam","sourceUrl":"https://whc.unesco.org/en/list/192/","sourceEvidence":"يصف موجز القيمة العالمية في صفحة اليونسكو تجمع البيوت البرجية من الطوب الطيني المجفف بالشمس في مدينة شبام المسوّرة."},
{"id":"math-01","categoryId":"math","category":"رياضيات ومنطق","difficulty":"easy","prompt":"ما ناتج 7 + 5؟","options":["10","11","12","13"],"correctIndex":2,"explanation":"بجمع 5 إلى 7 يكون الناتج 12.","verificationMethod":"الحساب المباشر؛ 7 + 5 = 12."}
]$moadbook_questions$::jsonb) AS q(
  id text, "categoryId" text, category text, difficulty text, prompt text, options jsonb,
  "correctIndex" smallint, explanation text, "sourceTitle" text, "sourceUrl" text, "sourceEvidence" text, "verificationMethod" text
)
ON CONFLICT (question_id) DO NOTHING;
